import data from "./san-diego-permits.json";

/**
 * Typed access to the San Diego ADU permit study aggregate. The JSON is
 * generated by `scripts/build-san-diego-adu-permits.mjs` from the City of
 * San Diego's open permit data and holds aggregate counts only: no address,
 * parcel or permit-holder field is ever read. Regenerate it with that script
 * rather than editing numbers by hand.
 *
 * @module content/adu/ca/san-diego-permits
 */

/** Counts for one year, one planning area, or the whole study. */
export interface PermitSummary {
  /** Building approvals issued that add at least one ADU or JADU. */
  approvals: number;
  /** ADUs plus JADUs those approvals add. */
  units: number;
  aduUnits: number;
  jaduUnits: number;
  /** ADUs the City's data flags as bonus-program units (a subset of aduUnits). */
  bonusAduUnits: number;
  /** ADUs restricted to very-low, low or moderate-income households. */
  affordableAduUnits: number;
  affordableByTier: { extremelyLow: number; veryLow: number; low: number; moderate: number };
  /** Approvals adding two or more units. */
  multiUnitApprovals: number;
  /** multiUnitApprovals / approvals, or null when the group is too small to quote. */
  multiUnitShare: number | null;
}

export interface PermitYear extends PermitSummary {
  year: number;
}

export interface PermitArea extends PermitSummary {
  /** City community planning area name. */
  name: string;
  unitsByYear: Record<string, number>;
}

export interface PermitStudy {
  /** Local date the City file was downloaded and aggregated. */
  generatedAt: string;
  /** First and last approval issue dates covered. */
  coverage: { from: string; to: string };
  source: string;
  boundaries: string;
  /** Smallest group whose share is quoted. */
  minGroup: number;
  excluded: { beforeFirstYear: number; withdrawn: number; companionWithoutUnitCount: number };
  /** Approvals whose location fell outside every planning area. */
  unmatched: number;
  largestApprovalUnits: number;
  approvalsByUnitCount: Record<"1" | "2" | "3-4" | "5-9" | "10+", number>;
  totals: PermitSummary;
  byYear: PermitYear[];
  /** Planning areas, most units first. */
  byArea: PermitArea[];
}

export const SAN_DIEGO_PERMIT_STUDY: PermitStudy = data as PermitStudy;

/** City of San Diego open-data catalog page for the permit file. */
export const PERMIT_DATASET_URL = "https://data.sandiego.gov/datasets/development-permits-set2/";
/** City of San Diego open-data catalog page for community planning areas. */
export const PLAN_AREAS_DATASET_URL = "https://data.sandiego.gov/datasets/cmty-plan/";

/** CSV of the planning-area table, one row per area. */
export function permitStudyCsv(study: PermitStudy = SAN_DIEGO_PERMIT_STUDY): string {
  const years = study.byYear.map((row) => row.year);
  const header = [
    "community_planning_area",
    "approvals",
    "units",
    "adu_units",
    "jadu_units",
    "bonus_adu_units",
    "income_restricted_adu_units",
    "approvals_adding_2plus_units",
    ...years.map((year) => `units_${year}`),
  ];
  const quote = (value: string | number) => {
    const text = String(value);
    return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
  };
  const lines = study.byArea.map((area) =>
    [
      area.name,
      area.approvals,
      area.units,
      area.aduUnits,
      area.jaduUnits,
      area.bonusAduUnits,
      area.affordableAduUnits,
      area.multiUnitApprovals,
      ...years.map((year) => area.unitsByYear[String(year)] ?? 0),
    ]
      .map(quote)
      .join(","),
  );
  return `${[header.join(","), ...lines].join("\n")}\n`;
}
